entries[87768] = { ["name"] = "Reins of the Onyx Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Onyx Cloud serpents are known to be more aggressive and daring than their cousins, the Heavenly Onyx Cloud Serpents.\"\nQuest:\nSurprise Attack!\nLocation:\nTownlong Steppes" }
entries[87769] = { ["name"] = "Reins of the Crimson Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Crimson Cloud Serpents are given to flights of fancy, striking out on a whim for seemingly random journeys, sometimes for days at a time.\"\nAchievement:\nGlory of the Pandaria Hero\nCategory:\nDungeons & Raids" }
entries[87771] = { ["name"] = "Reins of the Heavenly Onyx Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Heavenly Onyx Cloud Serpents are born with violet scales covering the entirety of their body. Over time, these scales darken to the color of onyx.\"\nDrop:\nSha of Anger\nLocation:\nKun-Lai Summit" }
entries[87773] = { ["name"] = "Reins of the Heavenly Crimson Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Heavenly Crimson Cloud Serpents are considered to be among the noblest of dragons.\"\nAchievement:\nGlory of the Pandaria Raider\nCategory:\nDungeons & Raids" }
entries[87774] = { ["name"] = "Reins of the Heavenly Golden Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Emperor Shaohao\n- Exalted\nSell Price:\n\"Warmth and hope emanate from this great creature, which glows like a sunrise over the mountains.\"\nVendor:\nMistweaver Ku\nZone:\nTimeless Isle\nFaction:\nEmperor Shaohao - Exalted" }
entries[87775] = { ["name"] = "Yu'lei, Daughter of Jade", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses Yu'lei, Daughter of Jade. This is a flying mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Warmth and wisdom emanate from this great creature, which glows like moonlight passing through the finest jade.\"\nVendor:\nMistweaver Xia\nZone:\nTimeless Isle\nCost:\n5000" }
entries[87776] = { ["name"] = "Reins of the Heavenly Azure Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Warmth and serenity emanate from this great creature, which glows like the cloudless sky of a summer afternoon.\"\nAchievement:\nLord of the Reins\nCategory:\nMounts" }
entries[87777] = { ["name"] = "Reins of the Astral Cloud Serpent", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"It is believed that Astral Cloud Serpents possess answers to some of life's greatest mysteries. Pity they can't talk.\"\nDrop:\nCache of Pure Energy" }
entries[87779] = { ["name"] = "Ancient Guo-Lai Cache Key", ["text"] = "Binds when picked up\nUse: Unlocks an Ancient Guo-Lai Cache in the Guo-Lai Halls." }
entries[87780] = { ["name"] = "Martar's Magnifying Glass", ["text"] = "Binds when picked up\nUnique\nTrinket\nUse: Summons Martar the Not-So-Smart to fight, adventure, and frolic with you for 10 min. (1 Hour Cooldown)\nSell Price:" }
entries[87781] = { ["name"] = "Reins of the Azure Riding Crane", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Azure Riding Crane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Golden Lotus\n- Exalted\nSell Price:\n\"The majestic crane is a treasured friend of the pandaren.\"\nVendor:\nJaluu the Generous\nZone:\nVale of Eternal Blossoms\nFaction:\nGolden Lotus - Exalted\nCost:" }
entries[87782] = { ["name"] = "Reins of the Golden Riding Crane", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Golden Riding Crane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Golden Lotus\n- Exalted\nSell Price:\n\"The crane is a symbol of wisdom and nobility, their ability to carry us into the skies is nothing short of miraculous. - Jaluu the Generous\"\nVendor:\nJaluu the Generous\nZone:\nVale of Eternal Blossoms\nFaction:\nGolden Lotus - Exalted\nCost:" }
entries[87783] = { ["name"] = "Reins of the Regal Riding Crane", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Regal Riding Crane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nRequires Golden Lotus\n- Exalted\nSell Price:\n\"The crane is a symbol of wisdom and nobility. Their ability to carry us into the skies is nothing short of miraculous. - Jaluu the Generous\"\nVendor:\nJaluu the Generous\nZone:\nVale of Eternal Blossoms\nFaction:\nGolden Lotus - Exalted\nCost:" }
entries[87784] = { ["name"] = "Reins of the Jungle Riding Crane", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Jungle Riding Crane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"A beloved mount in southern Pandaria, the jungle crane is known for its speed and agility honed over a lifetime of avoiding Krasari tigers.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[87785] = { ["name"] = "Reins of the Albino Riding Crane", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Albino Riding Crane.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:" }
entries[87786] = { ["name"] = "Reins of the Black Riding Yak", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Black Riding Yak.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Grummles traveling Kun-Lai Summit by night prefer to ride this dark-haired yak to remain unseen, though they remove the bells from its caparison first.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[87787] = { ["name"] = "Reins of the Modest Expedition Yak", ["text"] = "Remix: Pandaria\nBinds when picked up\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Brown Riding Yak.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\n\n\"Unlike its burden-bearing kin, this yak prefers to travel light and go no more than a mile at a time.\"\nWorld Event:\nWoW Remix: Mists of Pandaria" }
entries[87788] = { ["name"] = "Reins of the Grey Riding Yak", ["text"] = "Binds when picked up\nUnique\nMount\n(Account-wide)\nUse: Teaches you how to summon this mount.\nSummons and dismisses a rideable Grey Riding Yak.\nRequires level 1 to 80 ( 80)\nRequires Apprentice Riding\nSell Price:\n\"Riding Yaks are bred to be slimmer and more agile than their kin.\"\nVendor:\nUncle Bigpocket\nZone:\nKun-Lai Summit\nCost:" }
