entries[89197] = { ["name"] = "Windshear Cactus Seed", ["text"] = "Binds when picked up\nUse: Plant a Windshear Cactus Seed.\nRequires The Tillers - Revered\n\"The windshear cactus is covered in millions of fine needles which filter air as it passes through. Windwool fibers and scraps of material drifting in the breeze often collect on the cactus.\"\nSell Price:" }
